<?php
declare(strict_types=1);
function visibility_routes(PDO $db,array $auth,string $path,string $method): bool {
    if($path!=='/api/visibility'||$method!=='POST')return false;$input=metadata_object(metadata_json_body(),'Request');$targets=$input['targets']??null;if(!is_array($targets)||!count($targets)||count($targets)>2000)fail('validation','Choose 1–2000 visibility targets.');$ids=['track'=>[],'album'=>[]];foreach($targets as $raw){$target=metadata_object($raw,'Visibility target');$type=$target['type']??'';if(!is_string($type)||!isset($ids[$type]))fail('validation','Choose tracks or albums.');$id=journal_ids([$target['id']??null])[0];$ids[$type][$id]=true;}
    $visibility=$input['visibility']??null;if(!in_array($visibility,['private','public'],true))fail('validation','Choose Private or Public.');foreach(['dryRun','syncFuture']as $flag)if(array_key_exists($flag,$input)&&!is_bool($input[$flag]))fail('validation',$flag.' must be true or false.');if($auth['user']['role']==='listener')fail('forbidden','Your account cannot change track visibility.',403);
    $repo=new MetadataRepositoryNative($db);$direct=$repo->tracks(array_keys($ids['track']));$albums=$repo->albums(array_keys($ids['album']));if(count($direct)!==count($ids['track'])||count($albums)!==count($ids['album']))fail('not_found','A selected item was not found.',404);$children=[];foreach(array_chunk(array_keys($ids['album']),200)as $group)$children=array_merge($children,query_all($db,'SELECT id,rev,owner_id,album_id,artist_id,visibility,deleted FROM tracks WHERE deleted=0 AND album_id IN('.implode(',',array_fill(0,count($group),'?')).') LIMIT 10001',$group));$tracks=array_values(array_column([...$direct,...$children],null,'id'));$all=[...$tracks,...$albums];if(count($all)>10000)fail('too_large','Choose fewer tracks or albums.',413);
    foreach($all as $row)if($row['owner_id']!==$auth['user']['id']&&(!in_array($auth['user']['role'],['owner','admin'],true)||$visibility==='public'))fail('forbidden','Only the uploader can publish music. Admins can make it private.',403);
    $revisions=[];foreach($all as $row)$revisions[$row['id']]=(int)$row['rev'];if(array_key_exists('expectedRevs',$input))foreach(metadata_object($input['expectedRevs'],'Expected revisions')as $id=>$rev){if(!array_key_exists($id,$revisions)||(!is_int($rev)&&!is_float($rev))||floor((float)$rev)!==(float)$rev||$rev<0||$rev>9007199254740991)fail('validation','Expected revisions must belong to these targets.');if($revisions[$id]!== (int)$rev)journal_conflict([['table'=>isset($ids['album'][$id])?'albums':'tracks','id'=>$id]]);}
    $ops=[];$guards=[];$counts=[];$tracksUpdated=0;$albumsUpdated=0;foreach($tracks as $row){$guards[]=['table'=>'tracks','id'=>$row['id'],'rev'=>$row['rev']];$op=journal_op('tracks',$row,[...$row,'visibility'=>$visibility]);if($op){$ops[]=$op;$tracksUpdated++;}}
    foreach($albums as $row){$guards[]=['table'=>'albums','id'=>$row['id'],'rev'=>$row['rev']];$counts[]=['table'=>'tracks','column'=>'album_id','id'=>$row['id'],'count'=>count(array_filter($children,fn($track)=>$track['album_id']===$row['id']))];$after=[...$row,'visibility'=>$visibility];if(array_key_exists('syncFuture',$input))$after['sync_visibility']=$input['syncFuture']?1:0;$op=journal_op('albums',$row,$after);if($op){$ops[]=$op;$albumsUpdated++;}}
    if($visibility==='public'&&$ops)foreach(array_chunk(array_values(array_unique(array_column($all,'artist_id'))),200)as $group)foreach(query_all($db,'SELECT id,rev FROM artists WHERE deleted=0 AND id IN('.implode(',',array_fill(0,count($group),'?')).')',$group)as $row){$guards[]=['table'=>'artists','id'=>$row['id'],'rev'=>$row['rev']];array_unshift($ops,['table'=>'artists','id'=>$row['id'],'before'=>$row,'after'=>$row]);}
    $publicPlaylists=[];$publicAlbums=[];if($visibility==='private')foreach(array_chunk(array_column($tracks,'id'),200)as $group){$marks=implode(',',array_fill(0,count($group),'?'));foreach(query_all($db,"SELECT DISTINCT i.playlist_id AS id FROM playlist_items i JOIN playlists p ON p.id=i.playlist_id WHERE i.deleted=0 AND p.deleted=0 AND p.visibility='public' AND i.track_id IN(".$marks.')',$group)as $row)$publicPlaylists[$row['id']]=true;foreach(query_all($db,"SELECT DISTINCT a.id FROM albums a JOIN tracks t ON t.album_id=a.id WHERE a.deleted=0 AND a.visibility='public' AND t.id IN(".$marks.')',$group)as $row)$publicAlbums[$row['id']]=true;}
    $impact=['tracksUpdated'=>$tracksUpdated,'albumsUpdated'=>$albumsUpdated,'playlistsUpdated'=>0,'skippedNotOwned'=>0,'matchedTracks'=>count($tracks),'alsoIn'=>['publicPlaylists'=>count($publicPlaylists),'publicAlbums'=>count($publicAlbums)],'revisions'=>(object)$revisions];if($input['dryRun']??false)reply([...$impact,'dryRun'=>true,'changeId'=>null]);reply([...$impact,...journal_write($db,$auth,['summary'=>'Made '.count($tracks).' tracks '.$visibility,'ops'=>$ops,'guards'=>$guards,'counts'=>$counts])]);
}
